INSERT INTO `item_inventario` VALUES (1,'Potion','Restaura 20 de HP de um pokémon.','CURA_HP',20,0),(2,'Super Potion','Restaura 50 de HP de um pokémon.','CURA_HP',50,0),(3,'Hyper Potion','Restaura 200 de HP de um pokémon.','CURA_HP',200,0),(4,'Max Potion','Restaura 100% do HP de um pokémon.','CURA_HP',100,1),(5,'Revive','Revive um pokémon desmaiado com 50% de seu HP máximo.','REVIVE',50,1),(6,'Max Revive','Revive um pokémon desmaiado com 100% de seu HP máximo.','REVIVE',100,1),(7,'Ether','Restaura 10 PP de um movimento selecionado.','RESTAURA_PP',10,0),(8,'Max Elixir','Restaura todos os PPs de todos os movimentos.','RESTAURA_PP',99,0);
