CREATE DEFINER=`root`@`localhost` FUNCTION `fn_calcular_hp_max`(p_base INT, p_iv INT, p_ev INT, p_nivel INT) RETURNS int
    DETERMINISTIC
BEGIN
    RETURN FLOOR(((2 * p_base + p_iv + FLOOR(p_ev / 4)) * p_nivel) / 100) + p_nivel + 10;
END ;;
