DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gerar_encontro_selvagem`(IN p_mapa_id INT)
BEGIN
    DECLARE v_especie_id INT;
    DECLARE v_nivel_min, v_nivel_max, v_nivel_sorteado INT;

    SELECT especie_id, nivel_min, nivel_max
    INTO v_especie_id, v_nivel_min, v_nivel_max
    FROM encontro_mapa
    WHERE mapa_id = p_mapa_id
    ORDER BY (RAND() * (100.0 / taxa_chance)) ASC
    LIMIT 1;

    IF v_especie_id IS NULL THEN
        SELECT 'Nenhum pokémon selvagem encontrado neste mapa.' AS resultado;
    ELSE
        SET v_nivel_sorteado = FLOOR(v_nivel_min + (RAND() * (v_nivel_max - v_nivel_min + 1)));
        SELECT m.nome AS local,
               ep.nome AS pokemon_selvagem,
               v_nivel_sorteado AS nivel,
               t1.nome AS tipo1,
               t2.nome AS tipo2
        FROM especie_pokemon ep
        JOIN mapa m ON m.id = p_mapa_id
        JOIN tipo t1 ON ep.tipo1_id = t1.id
        LEFT JOIN tipo t2 ON ep.tipo2_id = t2.id
        WHERE ep.id_pokedex = v_especie_id;
    END IF;
END ;;
DELIMITER ;
